+
+    .required-note {
+      margin: 0 0 1rem;
+      color: var(--muted);
+      font-size: 0.92rem;
+    }
+
+    .form-field {
+      padding: 1rem;
+      border: 1px solid rgba(184, 194, 214, 0.22);
+      border-radius: 1rem;
+      background: rgba(11, 16, 32, 0.5);
+    }
+
+    .checkbox-row {
+      display: flex;
+      align-items: flex-start;
+      gap: 0.8rem;
+    }
+
