+      color: var(--text);
+      font-weight: 700;
+      cursor: pointer;
+    }
+
+    .required-marker {
+      color: var(--accent);
+      font-weight: 800;
+    }
+
+    .helper {
+      margin: 0.6rem 0 0 2.05rem;
+      color: var(--muted);
+      font-size: 0.94rem;
+    }
+
+    .error {
+      margin: 0.65rem 0 0 2.05rem;
+      color: var(--danger);
+      font-weight: 700;
+    }
+
+    .error[hidden] {
+      display: none;
+    }
+
+    button {
+      width: 100%;
+      margin-top: 1.25rem;
+      padding: 0.9rem 1rem;
+      border: 0;
+      border-radius: 999px;
+      color: #06111f;
+      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
+      box-shadow: 0 0.8rem 1.8rem rgba(56, 189, 248, 0.22);
+      font: inherit;
+      font-weight: 800;
+      cursor: pointer;
+    }
+
+    button:hover {
+      filter: brightness(1.06);
+    }
+
+    input[type="checkbox"]:focus-visible,
+    button:focus-visible {
+      outline: 3px solid #ffffff;
+      outline-offset: 4px;
+    }
+
+    .status {
+      min-height: 1.5rem;
+      margin: 1rem 0 0;
+      color: #bbf7d0;
+      font-weight: 700;
+    }
+
+    @media (forced-colors: active) {
+      .card,
+      .form-field,
+      button {
+        border: 1px solid CanvasText;
+        box-shadow: none;
+      }
+
+      button {
+        color: ButtonText;
+        background: ButtonFace;
+      }
+    }
+  </style>
+</head>
+<body>
+  <a class="skip-link" href="#main">Skip to main content</a>
+
+  <main id="main">
+    <section class="card" aria-labelledby="form-title">
+      <h1 id="form-title">Review terms</h1>
+      <p class="intro">Confirm your consent before continuing.</p>
+      <p class="required-note"><span aria-hidden="true">*</span> indicates a required field.</p>
+
+      <form id="consent-form" novalidate>
+        <div class="form-field">
+          <div class="checkbox-row">
+            <input
+              id="agree-terms"
+              name="agreeTerms"
+              type="checkbox"
+              required
+              aria-describedby="terms-helper terms-error"
+            >
+            <label for="agree-terms">
+              I agree to the terms of use <span class="required-marker" aria-hidden="true">*</span>
